import{J as e,n as t,ot as n,q as r}from"./chunks/framework.NDkVE8yV.js";var i=JSON.parse(`{"title":"Packet handlers share one shape in both directions, and serverbound handlers run in the input step","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Packet handlers share one shape in both directions, and serverbound handlers run in the input step"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/adr/0014-handlers-share-a-shape-and-run-in-the-input-step"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/adr/0014-handlers-share-a-shape-and-run-in-the-input-step"}]],"editSource":{"kind":"file","url":"https://github.com/JSPrismarine/JSPrismarine/edit/master/docs/adr/0014-handlers-share-a-shape-and-run-in-the-input-step.md"}},"headers":[],"relativePath":"adr/0014-handlers-share-a-shape-and-run-in-the-input-step.md","filePath":"adr/0014-handlers-share-a-shape-and-run-in-the-input-step.md","lastUpdated":1794437834000}`),a={name:`adr/0014-handlers-share-a-shape-and-run-in-the-input-step.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<div><h1 id="packet-handlers-share-one-shape-in-both-directions-and-serverbound-handlers-run-in-the-input-step" tabindex="-1">Packet handlers share one shape in both directions, and serverbound handlers run in the input step <a class="header-anchor" href="#packet-handlers-share-one-shape-in-both-directions-and-serverbound-handlers-run-in-the-input-step" aria-label="Permalink to “Packet handlers share one shape in both directions, and serverbound handlers run in the input step”">​</a></h1><p>Status: accepted</p><p>Packet handlers register by packet name and session phase, in one shape defined in <code>@jsprismarine/protocol</code> that the server and the client package both use. Each side supplies its own context type and keeps its own execution contract.</p><p>A serverbound handler declares its lane (<a href="/pr-preview/pr-2948/adr/0009-external-inputs-enter-once-per-tick.html">ADR 0009</a>), and what follows describes the input lane. Connection-lane and read-lane handlers run when their packet arrives and may stay asynchronous.</p><p>An input-lane handler for a player who is in a world takes a narrow context and not <code>Server</code>. It runs synchronously in that world&#39;s input step (<a href="/pr-preview/pr-2948/adr/0009-external-inputs-enter-once-per-tick.html">ADR 0009</a>) against loaded chunks only. Sends become outputs. An interaction with a chunk that is not loaded is rejected, as <code>BlockTarget</code> already does, and a synchronous accessor for loaded blocks replaces <code>getBlock</code> where a handler needs a <code>Block</code>. Work that needs I/O runs in the connection layer before the player joins a world: login, authentication, loading the player record and reading the operator list. Its result enters the world as a recorded input. Changing the operator list updates memory synchronously and persists off the tick.</p><p>The client has no world tick, so its handlers may stay asynchronous.</p><p>Today a handler takes the whole <code>Server</code>, can run between the awaits of <code>World.update</code>, and awaits its own sends. The client package rebuilt packet dispatch in <code>ClientPacketRegistry</code> because the server&#39;s handler shape cannot serve it. Most server handlers await nothing but sends, so most convert without changing behavior. The few that read chunks have synchronous equivalents on <code>World</code>, and the I/O handlers belong to the connection phase, not the simulation.</p></div>`,1)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};